// Initialize the matrix A as in the original PolyBench init_array()
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // A is logically A[i][j] in C, but stored as A(j, i) in Halide
    // (x = column j, y = row i).

    Var i("i"), j("j");
    Func A0("A0"), SPD("SPD");

    // First build the lower-triangular matrix (with diagonal set to 1),
    // matching the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // We express this as a single piecewise definition.
    Expr jj = j;
    Expr n_expr = n;

    Expr base_val = cast<num_t>(-(jj % n_expr));
    base_val = base_val / cast<num_t>(n_expr) + cast<num_t>(1);

    A0(j, i) =
        select(j == i,
               cast<num_t>(1),                          // diagonal override
               select(j <= i, base_val, cast<num_t>(0)));

    // Make the matrix positive semi-definite, as in the C code:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    // A = B;
    //
    // Map: A[r][t] -> A0(t, r); A[s][t] -> A0(t, s); B[r][s] -> SPD(s, r).
    RDom t(0, n, "t");

    SPD(j, i) = cast<num_t>(0);
    SPD(j, i) += A0(t, i) * A0(t, j);

    // Realize SPD into A. A has shape (n, n) with layout (x = j, y = i).
    SPD.realize(A);
}

int main(int argc, char *argv[]) {
