    int n = N;

    // Matrix A: logical A[i][j] stored as A(j, i).
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original C code.
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Build a Halide pipeline that computes the dot product:
    //
    // sum_{k=0..limit-1} A[i][k] * A[k][j]
    //
    // This corresponds to the inner k-loop in the LU kernel. We will call
    // this scalar pipeline from C++ loops that implement the i and j loops,
    // preserving the original data dependencies.
    // -------------------------------------------------------------------------
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    Param<int> i_param("i_param");
    Param<int> j_param("j_param");
    Param<int> limit_param("limit_param");  // upper limit for k

    // Reduction domain over k = 0 .. limit_param-1
    RDom k_dom(0, limit_param, "k");

    Func dot("dot");
    // 0-D Func: a single scalar value.
    dot() = cast<num_t>(0);
    // A[i][k] * A[k][j]  ->  A_param(k, i_param) * A_param(j_param, k)
    dot() += A_param(k_dom, i_param) * A_param(j_param, k_dom);

    // Simple schedule: compute at root.
    dot.compute_root();

    // Bind A buffer once; subsequent updates to A data are visible
    // to the Halide pipeline because the buffer points to the same memory.
    A_param.set(A);

    // JIT-compile the dot-product pipeline once.
    dot.compile_jit();

