    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // We compute the inner sum_{k}(A[i][k]*A[k][j]) with Halide, and perform
    // the final scalar updates to A[i][j] on the host. Data dependencies
    // between j values (for a fixed i) are preserved by the host loops.
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // First loop: j from 0 to i-1 (compute L part)
        for (int j = 0; j < i; j++) {
            // Configure parameters for dot product:
            // sum_{k = 0 .. j-1} A[i][k] * A[k][j]
            i_param.set(i);
            j_param.set(j);
            limit_param.set(j);

            Halide::Buffer<num_t> sum_buf = dot.realize();
            num_t sum = sum_buf();

            // Map A[i][j] -> A(j, i)
            num_t a_ij = A(j, i);
            num_t a_jj = A(j, j);

            // A[i][j] -= sum;  A[i][j] /= A[j][j];
            a_ij = (a_ij - sum) / a_jj;
            A(j, i) = a_ij;
        }

        // Second loop: j from i to n-1 (compute U part)
        for (int j = i; j < n; j++) {
            // Configure parameters for dot product:
            // sum_{k = 0 .. i-1} A[i][k] * A[k][j]
            i_param.set(i);
            j_param.set(j);
            limit_param.set(i);

            Halide::Buffer<num_t> sum_buf = dot.realize();
            num_t sum = sum_buf();

            num_t a_ij = A(j, i);

            // A[i][j] -= sum;
            a_ij = a_ij - sum;
            A(j, i) = a_ij;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

