    // C layout: A[i][j]
    // Halide layout: A(j, i)  (x = column j, y = row i)
    Var i("i"), j("j");
    Func A_init("A_init"), B_init("B_init");

    // Lower-triangular initialization:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: ((-j % n) / n) is integer division in C; reproduce with integer ops.
    Expr base_int = ((-j) % n) / n;       // Int division
    Expr base_val = cast<num_t>(base_int) + (num_t)1;  // Convert to num_t and add 1

    A_init(j, i) = select(j <= i,        // j in [0..i]
                          base_val,      // lower-triangular including diagonal
                          cast<num_t>(0));  // upper-triangular strictly above diagonal

    // Make the matrix positive semi-definite:
    // B[r][s] = sum_t A[r][t] * A[s][t];
    // A = B;
    RDom t(0, n, "t");
    B_init(j, i) = cast<num_t>(0);
    // C indexing: B[r][s] uses A[r][t] and A[s][t]
    // Halide: rows are 'i' and 's', cols are 'j' and 'r'
    // A[r][t]  -> A_init(t, r)  -> A_init(t, i)
    // A[s][t]  -> A_init(t, s)  -> A_init(t, j)
    B_init(j, i) += A_init(t, i) * A_init(t, j);

    // Realize B directly into the supplied buffer A.
    // After this, A contains the positive semi-definite matrix.
    B_init.realize(A);
}

// ---------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Allocate matrix A; C's A[i][j] corresponds to A(j, i)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A
    init_array(n, A);

    // -----------------------------------------------------------------
    // Halide representation of the LU kernel's inner k-summation
    //
    // Original kernel_lu:
    //
    // for (i = 0; i < N; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++)
    //       A[i][j] -= A[i][k] * A[k][j];
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < N; j++) {
    //     for (k = 0; k < i; k++)
    //       A[i][j] -= A[i][k] * A[k][j];
    //   }
    // }
    //
    // For a given (i, j), define:
    //   sum(i,j) = sum_{k < min(i,j)} A[i][k] * A[k][j]
    //
    // We'll compute sum(i,j) via Halide, with i and j as Params, and
    // apply the outer loops and updates on the host, reading/writing
    // A in-place. This preserves the loop-carried dependencies in i,j.
    // -----------------------------------------------------------------

    // Parameters representing the current matrix and loop indices
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    Param<int> n_param("n_param");
    Param<int> i_param("i_param");
    Param<int> j_param("j_param");

    // Reduction over k: 0 .. n-1
    RDom k(0, n_param, "k");

    // Sum over k of A[i][k] * A[k][j] where k < min(i, j)
    // C indexing -> Halide:
    //   A[i][k] -> A_param(k, i)
    //   A[k][j] -> A_param(j, k)
    Var dummy("dummy");
    Func lu_sum("lu_sum");

    Expr limit = Halide::min(i_param, j_param);
    lu_sum(dummy) = cast<num_t>(0);
    lu_sum(dummy) += select(k < limit,
                            A_param(k, i_param) * A_param(j_param, k),
                            cast<num_t>(0));

    // Bind the parameters
    A_param.set(A);
    n_param.set(n);

    // JIT-compile the reduction
    lu_sum.compile_jit();

    // Buffer to hold the scalar sum result (1 element)
    Halide::Buffer<num_t, 1> sum_buf(1);

    // -----------------------------------------------------------------
    // Execute the LU kernel and measure execution time
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // First loop: j < i
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute sum_{k < j} A[i][k] * A[k][j]
            lu_sum.realize(sum_buf);
            num_t sum = sum_buf(0);

            // C: A[i][j] -= sum; A[i][j] /= A[j][j];
            // Halide buffer: A(j, i) corresponds to A[i][j]
            A(j, i) = (A(j, i) - sum) / A(j, j);
        }

        // Second loop: j >= i
        for (int j = i; j < n; j++) {
            i_param.set(i);
