#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (e.g., N, DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions (e.g., N for LU, DATA_TYPE)
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization (translated from init_array in lu.c)
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // In C, A is declared as A[n][n] and accessed as A[i][j],
    // where i is the row and j is the column. Memory is row-major,
    // so j is the fastest-varying index.
    //
    // In Halide, we represent this as Buffer(x=j, y=i), i.e.,
    // A(j, i) corresponds to C's A[i][j].

    Var j("j"), i("i");
    Func L("L");   // initial lower-triangular-like matrix
    Func Bf("B");  // final positive semi-definite matrix

    // First, construct the lower-triangular matrix L that matches the
    // first part of init_array.
    //
    // C code:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Mapping to Halide: A[i][j] -> L(j, i).
    Expr neg_j = -j;
    Expr mod = neg_j % n;
    Expr val_lower = cast<num_t>(mod) / cast<num_t>(n) + cast<num_t>(1);

    L(j, i) = select(j < i,
                     val_lower,                        // below diagonal
                     j == i,
                     cast<num_t>(1),                   // diagonal
                     cast<num_t>(0));                  // above diagonal

    // Next, make the matrix positive semi-definite:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t]
    //
    // In C:
    // for (r = 0; r < n; ++r)
    //   for (s = 0; s < n; ++s)
    //     B[r][s] = 0;
    // for (t = 0; t < n; ++t)
    //   for (r = 0; r < n; ++r)
    //     for (s = 0; s < n; ++s)
    //       B[r][s] += A[r][t] * A[s][t];
    // for (r = 0; r < n; ++r)
    //   for (s = 0; s < n; ++s)
    //     A[r][s] = B[r][s];
    //
    // Using our mapping:
    // A[r][t] -> L(x=t, y=r)
    // A[s][t] -> L(x=t, y=s)
    // B[r][s] -> Bf(x=s, y=r)
    //
    // So:
    // Bf(s, r) = sum_{t} L(t, r) * L(t, s)

    RDom t(0, n, "t");

    Bf(j, i) = cast<num_t>(0);
    Bf(j, i) += L(t, i) * L(t, j);

    // Realize Bf directly into the provided buffer A.
    Bf.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Allocate matrix A. We use (x=j, y=i) so that the first dimension
    // is the fastest-varying, matching C's row-major layout.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize data (uses Halide pipeline above).
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Halide setup for LU kernel
    // -------------------------------------------------------------------------

    // ImageParam for the matrix A. It will be updated in-place in the Buffer,
    // but Halide only reads from it; writes are done on the host.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Scalar iteration parameters: i and j from the original C loops.
    Param<int> i_param("i");
    Param<int> j_param("j");

    // Bind the matrix buffer to the ImageParam.
    A_param.set(A);

    // We will use Halide to compute each scalar update, reducing over k.
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++) {
    //   // Compute L entries A[i][j] for j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //
    //   // Compute U entries A[i][j] for j >= i
    //   for (j = i; j < N; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // We express each scalar update using Halide, with host-driven
    // loops over i and j, and a Halide reduction over k.

    // Func to compute a single L-entry A[i][j] for j < i:
    // A[i][j] = (A[i][j] - sum_{k=0..j-1} A[i][k] * A[k][j]) / A[j][j]
    Func compute_L("compute_L");
    {
        RDom rL(0, j_param, "rL");

        // Mapping: A[i][k] -> A_param(x=k,   y=i_param)
        //          A[k][j] -> A_param(x=j_param, y=rL)
        Expr sumL = sum(A_param(rL, i_param) * A_param(j_param, rL));

        // A[i][j] and A[j][j] in our (x=j, y=i) buffer layout:
        Expr Aij = A_param(j_param, i_param);      // A[i][j]
        Expr Ajj = A_param(j_param, j_param);      // A[j][j]

        compute_L() = (Aij - sumL) / Ajj;
    }

    // Func to compute a single U-entry A[i][j] for j >= i:
    // A[i][j] = A[i][j] - sum_{k=0..i-1} A[i][k] * A[k][j]
    Func compute_U("compute_U");
    {
        RDom rU(0, i_param, "rU");

        // Mapping: A[i][k] -> A_param(x=k,   y=i_param)
        //          A[k][j] -> A_param(x=j_param, y=rU)
        Expr sumU = sum(A_param(rU, i_param) * A_param(j_param, rU));

        Expr Aij = A_param(j_param, i_param);      // A[i][j]

        compute_U() = Aij - sumU;
    }

    // JIT-compile the scalar kernels once.
    compute_L.compile_jit();
    compute_U.compile_jit();

    // -------------------------------------------------------------------------
    // Run kernel and measure time
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Host-driven loops over i and j, matching the original C code.
    for (int i = 0; i < n; i++) {
        // j < i: compute L-part entries in row i
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            Halide::Buffer<num_t> scalar = compute_L.realize();
            // A(i,j) -> A(j, i) in our Buffer
            A(j, i) = scalar();
        }

        // j >= i: compute U-part entries in row i
        for (int j = i; j < n; j++) {
            i_param.set(i);
            j_param.set(j);

            Halide::Buffer<num_t> scalar = compute_U.realize();
            A(j, i) = scalar();
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optionally print the result matrix (to avoid dead-code elimination)
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Print in row-major order: A[i][j] -> A(j, i)
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds with 6 decimal places.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
