#include "Halide.h"

// include common definitions (PolyBench-style sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for LU
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize matrix A as in the original PolyBench LU benchmark:
 *
 * 1. Fill A with a lower-triangular pattern plus ones on the diagonal.
 * 2. Make A positive semi-definite by replacing it with A * A^T.
 *
 * C layout:   A[i][j], i=row, j=col
 * Halide buf: A(j, i), x=col, y=row
 */
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    Var x("x"), y("y");

    // Step 1: lower-triangular initialization with ones on the diagonal.
    // Original C:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    Func init_lower("init_lower");
    {
        Expr j = x;
        Expr i = y;
        Expr n_expr = n;

        // Compute (-j % n) / n as integer arithmetic, then cast to num_t and add 1.
        // This matches the original C semantics (integer division).
        Expr minus_j = -j;
        Expr mod = minus_j % n_expr;
        Expr int_div = mod / n_expr;  // integer division
        Expr base = cast<num_t>(int_div) + Expr((num_t)1);

        // Lower triangle (including diagonal) gets 'base', upper triangle gets 0.
        Expr val = select(j <= i, base, Expr((num_t)0));

        // Override diagonal with exactly 1.
        init_lower(x, y) = select(j == i, Expr((num_t)1), val);
    }

    // Step 2: make the matrix positive semi-definite: B = A * A^T, then A = B.
    // Original C:
    // B[r][s] = 0;
    // B[r][s] += A[r][t] * A[s][t];
    // A[r][s] = B[r][s];
    Func psd("psd");
    {
        RDom t(0, n, "t");

        // A layout: init_lower(col=x, row=y)
        // We want: B[r][s] = sum_t A[r][t] * A[s][t]
        // In Halide: psd(x=s, y=r) = sum_t init_lower(t, r) * init_lower(t, s)
        psd(x, y) = cast<num_t>(0);
        psd(x, y) += init_lower(t, y) * init_lower(t, x);
    }

    // Realize directly into the provided buffer A.
    psd.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from lu.hpp / defines.hpp)
    int n = N;

    // Matrix A: Buffer layout is (x=col, y=row).
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A.
    init_array(n, A);

    // Halide representation of the LU update for a single element A[i][j].
    //
    // Original kernel (C):
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // We express the effect on a *single* element as:
    //
    // Let i = row, j = col.
    // sum = Σ_{k=0..min(i,j)-1} A[i][k] * A[k][j]
    //
    // if (j < i):  // L-part
    //   A[i][j] = (A[i][j] - sum) / A[j][j];
    // else:        // U-part (including diagonal)
    //   A[i][j] = A[i][j] - sum;
    //
    // In Halide-buffer coordinates: A(j, i) = ...
    // We treat the inner k-loop as a Halide reduction and keep the
    // outer (i, j) loops on the host, updating one scalar at a time.

    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    Param<int> i_param("i"), j_param("j");

    // Bind the ImageParam to our buffer once. It will see subsequent
    // updates to A because they occur in the same underlying memory.
    A_param.set(A);

    // Reduction domain for the sum over k = 0 .. min(i, j)-1.
    RDom k("k", 0, Halide::min(i_param, j_param));

    // Scalar Func that computes the new value for A[i][j].
    Func elem("elem");
    {
        // sum_k A[i][k] * A[k][j]  ->  in buffer coords: A_param(k, i) * A_param(j, k)
        Expr sum_val = sum(A_param(k, i_param) * A_param(j_param, k));

        // Denominator: A[j][j] for L-part (j < i), 1 otherwise.
        Expr denom = select(j_param < i_param,
                            A_param(j_param, j_param),
                            Expr((num_t)1));

        // New value for A[i][j].
        Expr new_val = (A_param(j_param, i_param) - sum_val) / denom;

        elem() = new_val;
    }

    // JIT-compile the scalar update kernel once.
    elem.compile_jit();

    // Time the LU factorization.
    auto start = std::chrono::high_resolution_clock::now();

    // Perform the LU decomposition, updating A in place.
    // Host loops over i and j, Halide handles the inner reduction over k.
    for (int i = 0; i < n; i++) {
        i_param.set(i);
        for (int j = 0; j < n; j++) {
            j_param.set(j);

            // Compute the updated A[i][j] as a scalar.
            Halide::Buffer<num_t> val_buf = elem.realize();
            num_t val = val_buf();

            // Store back into A (note: A(j, i) corresponds to A[i][j] in C).
            A(j, i) = val;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the resulting matrix (matches gemm.cpp style).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds with 6 decimal places.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
